const zero = runScenario("z0-exit0", 0);
console.log("before (exit 0, volatile output) -> breaker:", JSON.stringify(zero ?? null));
console.log("RESULT:", nonzero?.detector === "global_circuit_breaker" && !zero ? "PASS" : "FAIL");
